"""Regenerate dictionary/data-dictionary.md from dictionary/schema.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
s = json.loads((ROOT / "dictionary" / "schema.json").read_text(encoding="utf-8"))
lines = ["# Data dictionary, version " + s["version"], "",
         "Generated from `dictionary/schema.json`, which the record checks use. Do not edit this file by hand; edit the schema and run `python scripts/make_dictionary.py`.", "",
         "Fields marked AI-filled are filled by the AI only after the editor's core-field commit, checked by the editor against the page, and kept out of all agreement figures.", ""]
for t, v in s["tables"].items():
    lines += [f"## {t}", "", f"Key: `{v['key']}`", "", "| Field | Required | Allowed values | Meaning |", "|---|---|---|---|"]
    for f, r in v["fields"].items():
        codes = "; ".join(r.get("codes", []) or r.get("codes_multi", []))
        if r.get("codes_multi"):
            codes = "any of: " + codes
        lines.append(f"| `{f}` | {'yes' if r.get('required') else 'no'} | {codes} | {r['desc']} |")
    lines.append("")
(ROOT / "dictionary" / "data-dictionary.md").write_text("\n".join(lines), encoding="utf-8")
print("written")
